/* Word Guesser. Loaded on demand by js/arcade.js the first time the game is opened.
   Guess the secret 5-letter word in 6 tries. After each guess the tiles show which letters are right:
   green is the right letter in the right place, gold is in the word but somewhere else, dark is not in the word.
   Solve it and a new word comes. Fewer guesses give more points. Miss a word and the game is over. */
(() => {
  const { ctx, C, font, shuffle, sfx, setScore, over, tween, pop } = Arcade;

  // The secret words: common English words, picked by hand.
  const ANSWERS = 'about above actor acute admit adopt adult after again agent agree ahead alarm album alert alike alive allow alone along alter amber angel anger angle angry ankle apart apple apply apron arena argue arise armor arrow aside asset atlas attic audio avoid awake award aware awful bacon badge badly baker basic basin batch beach beard beast begin being belly below bench berry birth black blade blame blank blast blaze blend bless blind blink block bloom board boast bonus boost booth bound brain brake brand brave bread break brick bride brief bring brisk broad broom brown brush build bunch burst cabin cable camel candy canoe cargo carry catch cause chain chair chalk charm chart chase cheap check cheek cheer chess chest chick chief child chili chill choir chunk cider civic claim clamp clash class clean clear clerk click cliff climb clock close cloth cloud clown coach coast cocoa color comet comic coral couch cough count court cover crack craft crane crash crawl crazy cream creek crisp crowd crown crumb crust cubic curve cycle daily dairy daisy dance dealt delay depth diary dizzy dodge donut doubt dough draft drain drama dream dress drift drill drink drive eager eagle early earth easel eight elbow elder empty enjoy enter entry equal error event exact exist extra fable faint fairy faith false fancy feast fence ferry fetch fever field fifty fight final flame flash fleet flock flood floor flour fluid flute focus force forge forth found frame fresh frost fruit fudge funny gamer gauge ghost giant given glass globe glove goose grace grade grain grand grape graph grass great greed green greet grill groan group grove guard guess guest guide habit happy harsh haste heart heavy hedge hello hippo hobby honey honor horse hotel house human humor hurry ideal igloo image index inner input irony ivory jelly jewel joint jolly judge juice jumbo kayak kebab knife knock koala label laser latch laugh layer learn lemon level light lilac limit linen liver llama lodge logic loose lucky lunar lunch magic major mango maple march match mayor medal melon mercy merit merry metal meter midst minor model money month moose motor mound mount mouse mouth movie muddy music naval nerve never night ninja noble noise north novel nurse ocean offer often olive onion opera orbit order otter outer owner oxide paint panda panel paper party pasta patch peace peach pearl pedal penny perch phone photo piano piece pilot pizza place plain plane plant plate plaza plush point polar porch pouch pound power press price pride prime print prize proof proud pulse punch puppy queen quest quick quiet quilt quote radar radio rainy raise rally ranch range rapid raven razor reach react ready realm rebel relax relay remix reply rhyme rider ridge right rival river roast robin robot rocky rodeo rough round route royal rugby ruler rusty salad salsa sauce scale scarf scene scoop score scout shade shake shape share shark sharp sheep sheet shelf shell shine shiny shirt shock shore short shout shrub sight silly since skate skill skirt skull slate sleep slice slide slope smart smell smile smoke snack snail snake sneak solar solid solve sound south space spare spark speak speed spell spend spice spike spine spoon sport spray squad stack staff stage stair stamp stand start state steam steel steep stick still stone stool storm story stove straw strip stuck study style sugar sunny super swamp sweat sweep sweet swift swing sword table taste teach teeth thank theme thick thief thing think thorn three throw thumb tiger timer toast today token topic torch total touch tough towel tower toxic trace track trade trail train treat trend trial tribe trick troop truck truly trunk trust truth tulip tutor twist uncle under union unity until upper upset urban usage usual valid value vapor vault video vigor viola virus visit vital vivid vocal voice wagon waist watch water whale wheat wheel where while whirl white whole width witch woman world worry wound woven wrist write wrong yacht yeast young youth zebra'.split(' ');
  // Every word that counts as a guess (from the MIT-licensed "word-list" package by Sindre Sorhus), packed 5 letters at a time.
  const PACKED = '';
  let dict = null;
  const isWord = (w) => {
    if (!dict) { dict = new Set(ANSWERS); for (let i = 0; i < PACKED.length; i += 5) dict.add(PACKED.slice(i, i + 5)); }
    return dict.has(w);
  };

  const W = 400, H = 620, ROWS = 6, LEN = 5, TILE = 52, GAP = 6;
  const GX = (W - (LEN * TILE + (LEN - 1) * GAP)) / 2, GY = 54;
  const GREEN = '#3f9a5c', GOLD = '#d1a33a', GREY = '#3b3452', EDGE = '#3a3052';
  const KEYS = ['QWERTYUIOP', 'ASDFGHJKL', '>ZXCVBNM<']; // > is Enter, < is Backspace.
  const KW = 34, KH = 50, KG = 5, KY = 440;
  const RANK = { absent: 1, present: 2, correct: 3 };
  const FILL = { absent: GREY, present: GOLD, correct: GREEN };

  // Marks each letter of a guess, counting repeated letters the fair way.
  function score(guess, answer) {
    const res = Array(LEN).fill('absent'), left = {};
    for (let i = 0; i < LEN; i++) { if (guess[i] === answer[i]) res[i] = 'correct'; else left[answer[i]] = (left[answer[i]] || 0) + 1; }
    for (let i = 0; i < LEN; i++) if (res[i] !== 'correct' && left[guess[i]]) { res[i] = 'present'; left[guess[i]]--; }
    return res;
  }

  const words = {
    W, H, color: 'var(--gold)', title: 'Word Guesser', label: 'Score', typing: true,
    intro: 'Guess the 5-letter word in 6 tries. Green: right spot. Gold: in the word. Solve as many as you can in a row.',
    hint: 'Type a word and press <kbd>Enter</kbd>, or tap the letters. <kbd>Esc</kbd> to leave',
    reset() {
      this.deck = shuffle(ANSWERS.slice()); this.score = 0; this.solved = 0; this.t = 0;
      this.ptr = null; this.later = null; this.newWord();
    },
    newWord() {
      this.answer = this.deck[this.solved % this.deck.length];
      this.rows = Array.from({ length: ROWS }, () => ({ text: '', marks: null, flip: [], hop: [], dx: 0 }));
      this.row = 0; this.busy = false; this.keyState = {}; this.msg = ''; this.msgA = { a: 0 };
      this.pulse = Array.from({ length: LEN }, () => ({ s: 1 }));
      this.show = { a: 0 }; tween(this.show, { a: 1 }, 350, { ease: 'out' });
    },
    say(text, ms = 1400) {
      this.msg = text; this.msgA = { a: 1 };
      tween(this.msgA, { a: 0 }, 400, { delay: ms, ease: 'in' });
    },
    type(ch) {
      if (this.busy || this.row >= ROWS) return;
      const r = this.rows[this.row];
      if (ch === '<') { if (r.text.length) { r.text = r.text.slice(0, -1); sfx.tone(300, 0.03, 'square', 0.02); } return; }
      if (ch === '>') { this.enter(); return; }
      if (r.text.length >= LEN) return;
      r.text += ch.toLowerCase();
      const p = this.pulse[r.text.length - 1]; p.s = 1.14; tween(p, { s: 1 }, 160, { ease: 'out' });
      sfx.tone(520, 0.03, 'square', 0.02);
    },
    enter() {
      const r = this.rows[this.row];
      if (r.text.length < LEN) { this.wobble(r); this.say('Not enough letters'); return; }
      if (!isWord(r.text)) { this.wobble(r); this.say('Not in the word list'); return; }
      r.marks = score(r.text, this.answer);
      r.flip = r.marks.map(() => ({ f: 0 }));
      this.busy = true;
      r.flip.forEach((f, i) => tween(f, { f: 1 }, 300, { delay: i * 200, ease: 'inout', done: () => {
        sfx.tone([330, 440, 554][RANK[r.marks[i]] - 1], 0.06, 'triangle', 0.05);
        if (i === LEN - 1) this.judge(r);
      } }));
    },
    wobble(r) { sfx.hit(); r.dx = 1; tween(r, { dx: 0 }, 420, { ease: 'out' }); },
    judge(r) {
      r.text.split('').forEach((ch, i) => { const k = r.marks[i]; if (!this.keyState[ch] || RANK[k] > RANK[this.keyState[ch]]) this.keyState[ch] = k; });
      if (r.text === this.answer) {
        const guesses = this.row + 1, pts = (ROWS + 1 - guesses) * 10;
        this.score += pts; this.solved++; setScore(this.score);
        this.say(['GENIUS!', 'AMAZING!', 'GREAT!', 'NICE!', 'GOOD!', 'PHEW!'][guesses - 1], 900);
        pop(W / 2, GY + this.row * (TILE + GAP) - 6, '+' + pts, C.lime, 14);
        r.hop = Array.from({ length: LEN }, () => ({ y: 0 }));
        r.hop.forEach((h, i) => tween(h, { y: -16 }, 180, { delay: i * 90, ease: 'out', yoyo: true }));
        sfx.win();
        this.later = { t: 1.5, fn: () => this.newWord() };
        return;
      }
      this.row++;
      if (this.row >= ROWS) {
        this.say(this.answer.toUpperCase(), 99999);
        this.later = { t: 1.4, fn: () => over(this.score, 'The word was ' + this.answer.toUpperCase() + '. You solved ' + this.solved + ' word' + (this.solved === 1 ? '' : 's') + '.') };
        return;
      }
      this.busy = false;
    },
    key(e, down) {
      if (!down || e.ctrlKey || e.metaKey || e.altKey) return;
      if (e.key === 'Enter') { e.preventDefault(); this.type('>'); } else if (e.key === 'Backspace') { e.preventDefault(); this.type('<'); } else if (/^[a-zA-Z]$/.test(e.key)) this.type(e.key);
    },
    point(p) { this.ptr = p; },
    tap() {
      const p = this.ptr; if (!p) return;
      const k = this.keyAt(p.x, p.y); if (k) { this.type(k); this.pressed = { k, a: 1 }; tween(this.pressed, { a: 0 }, 200); }
    },
    keyRects() {
      if (this.rects) return this.rects;
      const out = [];
      KEYS.forEach((row, ri) => {
        const wide = ri === 2 ? 52 : KW;
        const total = row.split('').reduce((s, k) => s + (k === '>' || k === '<' ? wide : KW), 0) + (row.length - 1) * KG;
        let x = (W - total) / 2;
        for (const k of row) { const w = k === '>' || k === '<' ? wide : KW; out.push({ k, x, y: KY + ri * (KH + 6), w, h: KH }); x += w + KG; }
      });
      return (this.rects = out);
    },
    keyAt(x, y) {
      // A touch just between two keys still counts for the nearest one.
      let best = null, bd = 18;
      for (const r of this.keyRects()) {
        const dx = Math.max(r.x - x, 0, x - r.x - r.w), dy = Math.max(r.y - y, 0, y - r.y - r.h), d = Math.hypot(dx, dy);
        if (d < bd || (d === 0 && bd > 0)) { best = r; bd = d; if (d === 0) break; }
      }
      return best && best.k;
    },
    update(dt) {
      this.t += dt;
      // Waits run on the game's clock, so they also wait while the game is paused.
      if (this.later && (this.later.t -= dt) <= 0) { const fn = this.later.fn; this.later = null; fn(); }
    },
    draw() {
      ctx.fillStyle = C.bg; ctx.fillRect(0, 0, W, H);
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.font = font(9); ctx.fillStyle = C.muted;
      ctx.fillText('WORD ' + (this.solved + 1) + '   ·   SOLVED ' + this.solved, W / 2, 26);
      ctx.globalAlpha = this.show.a;
      this.rows.forEach((r, ri) => {
        const shakeX = Math.sin(r.dx * 30) * 10 * r.dx;
        for (let i = 0; i < LEN; i++) {
          const x = GX + i * (TILE + GAP) + shakeX, y = GY + ri * (TILE + GAP) + (r.hop[i] ? r.hop[i].y : 0);
          const ch = r.text[i] || '', f = r.flip[i] ? r.flip[i].f : 0, shown = f >= 0.5;
          const sy = r.flip[i] ? Math.abs(Math.cos(f * Math.PI)) : 1;
          const s = ri === this.row && !r.marks && this.pulse[i] ? this.pulse[i].s : 1;
          ctx.save(); ctx.translate(x + TILE / 2, y + TILE / 2); ctx.scale(s, sy * s);
          if (shown) { ctx.fillStyle = FILL[r.marks[i]]; ctx.fillRect(-TILE / 2, -TILE / 2, TILE, TILE); }
          else {
            ctx.fillStyle = '#120e1c'; ctx.fillRect(-TILE / 2, -TILE / 2, TILE, TILE);
            ctx.strokeStyle = ch ? '#6d6390' : EDGE; ctx.lineWidth = 2; ctx.strokeRect(-TILE / 2 + 1, -TILE / 2 + 1, TILE - 2, TILE - 2);
          }
          if (ch) { ctx.fillStyle = C.ink; ctx.font = font(20); ctx.fillText(ch.toUpperCase(), 0, 2); }
          ctx.restore();
        }
      });
      ctx.globalAlpha = 1;
      if (this.msgA.a > 0.01) {
        ctx.globalAlpha = Math.min(1, this.msgA.a * 1.5);
        ctx.font = font(11); const tw = ctx.measureText(this.msg).width + 28;
        ctx.fillStyle = C.ink; ctx.fillRect(W / 2 - tw / 2, 404, tw, 28);
        ctx.fillStyle = C.bg; ctx.fillText(this.msg, W / 2, 419);
        ctx.globalAlpha = 1;
      }
      for (const r of this.keyRects()) {
        const st = this.keyState[r.k.toLowerCase()];
        const hit = this.pressed && this.pressed.k === r.k ? this.pressed.a : 0;
        ctx.fillStyle = st ? FILL[st] : '#4a4166';
        if (st === 'absent') ctx.fillStyle = '#1c1729';
        ctx.fillRect(r.x, r.y + hit * 2, r.w, r.h);
        if (hit) { ctx.fillStyle = 'rgba(255,255,255,' + hit * 0.3 + ')'; ctx.fillRect(r.x, r.y + hit * 2, r.w, r.h); }
        ctx.fillStyle = st === 'absent' ? '#6d6390' : C.ink;
        ctx.font = font(r.k === '>' || r.k === '<' ? 8 : 12);
        ctx.fillText(r.k === '>' ? 'ENTER' : r.k === '<' ? 'DEL' : r.k, r.x + r.w / 2, r.y + r.h / 2 + 1 + hit * 2);
      }
      ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
    },
  };

  Arcade.register('words', words);
})();
